import pathlib,pandas as pd,numpy as np
p=pathlib.Path('/opt/mts/ga6/runs/independent_review');d=pd.read_parquet(p/'trade_entries_prior_features.parquet');d['event']=d.ticker.astype(str)+'|'+d.entry_date.astype(str);d=d.sort_values(['event','chromosome']).drop_duplicates('event');b=pd.to_numeric(d['prior_ga4_breadth_above_sma_200__v1'],errors='coerce');d['band']=pd.cut(b,[-np.inf,.45,.50,.55,.60,np.inf],labels=['le45','45to50','50to55','55to60','gt60'],right=True)
print('COLUMNS',list(d.columns));stats=d.groupby('band',observed=True).agg(events=('event','size'),mean_return=('trade_return','mean'),median_return=('trade_return','median'),win_rate=('trade_return',lambda x:(x>0).mean()),loss_rate=('trade_return',lambda x:(x<0).mean()),mean_mae=('mae', 'mean') if 'mae' in d.columns else ('trade_return','mean'));print(stats.to_string());stats.to_csv(p/'BREADTH_EVENT_BAND_STATISTICS.csv')
